/**
 * @file recipes.h
 * @brief Built-in recipe data for the 菜谱 app (hardware-free, shared with the simulator).
 *
 * The data is generated by sim/tools/gen_recipes.py into recipes_data.inc and lives in flash (const arrays,
 * no RAM). Photos are 2 bpp BWRY, kPhotoW x kPhotoH, 4 pixels per byte MSB first, kPhotoStride bytes per row,
 * codes = rawdraw::Color (00 black, 01 white, 10 yellow, 11 red).
 */

#ifndef COMMON_RECIPES_H
#define COMMON_RECIPES_H

#include <cstdint>

namespace recipes {

constexpr int kPhotoW = 180;
constexpr int kPhotoH = 139;
constexpr int kPhotoStride = (kPhotoW + 3) / 4;
constexpr int kPhotoBytes = kPhotoStride * kPhotoH;

struct RecipeItem {
    const char* name;
    const char* amount;
};

struct Recipe {
    const char* id;
    const char* title;
    const char* tag;       ///< category shown in the header bar, e.g. 海鲜
    const char* serving;   ///< what the amounts are for, e.g. "1 人份"
    int stars;             ///< difficulty, 1-5
    int kcal;
    int minutes;           ///< 0 = the source gives no total time
    const char* intro;
    const char* tip;       ///< optional one-line hint, "" = none
    const RecipeItem* items;
    int item_count;
    const char* const* steps;
    int step_count;
    const uint8_t* photo;  ///< kPhotoBytes bytes
};

int Count();
const Recipe& Get(int index);

}  // namespace recipes

#endif  // COMMON_RECIPES_H
